@users_bp.route("/<int:user_id>/role", methods=["PUT"])
@require_auth
def set_user_role(user_id: int):
    payload = request.get_json(silent=True) or {}
    new_role = payload.get("role", "user")
    session = get_session()
    user = session.get(User, user_id)
    if user is None:
        return jsonify({"error": "not found"}), 404
    user.role = new_role
    session.commit()
    return jsonify(user.to_dict())

def require_auth(fn):
    """Reject the request unless a valid user token is presented."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.current_user = user
        return fn(*args, **kwargs)
    return wrapper

def set_user_role(user_id: int):
    payload = request.get_json(silent=True) or {}
    new_role = payload.get("role", "user")
    session = get_session()
    user = session.get(User, user_id)
    if user is None:
        return jsonify({"error": "not found"}), 404
    user.role = new_role
    session.commit()

def is_owner_or_admin(user: User, owner_id: int) -> bool:
    """Ownership check used for per-object access (orders, profiles)."""
    return user.id == owner_id or user.role == "admin"

